parameters.query:
SELECT json_build_object(
  'settings', (SELECT row_to_json(s) FROM cypress_rr_settings s WHERE s.id = 1),
  'reps', COALESCE((SELECT json_agg(r ORDER BY r.position, r.id) FROM cypress_rr_reps r), '[]'::json),
  'recent', COALESCE((
    SELECT json_agg(DISTINCT a.contact_id) FROM cypress_rr_assignments a, cypress_rr_settings s
    WHERE s.id = 1 AND a.joined_list_at >= COALESCE(s.list_last_join_at, now()) - interval '1 day'
  ), '[]'::json)
) AS body;

parameters.jsCode:
// rr-assign: from the list's join-order pages, the members who joined since the last poll.
// HubSpot returns list 276's members newest first (checked 2026-10-30: 250 of 250 in descending order), so the HTTP
// node reads from the top and stops paging once a page reaches members already seen.
// The first poll ever only records the newest join time (baseline), so the list's history isn't assigned.
const MAX_PER_RUN = 100;

function pickNew(settings, recentIds, pages) {
  const members = [];
  for (const page of pages) {
    for (const r of page?.results || []) {
      const id = String(r.recordId ?? r.id ?? '');
      const ts = Date.parse(r.membershipTimestamp ?? r.timestamp ?? '');
      if (id && Number.isFinite(ts)) members.push({ id, ts });
    }
  }
  const newest = members.reduce((m, x) => Math.max(m, x.ts), 0);

  if (!settings.list_initialized) {
    return { baseline: true, members: [], cursor: { list_last_join_at: newest ? new Date(newest).toISOString() : '' } };
  }

  const lastJoin = settings.list_last_join_at ? Date.parse(settings.list_last_join_at) : Infinity;
  const recent = new Set((recentIds || []).map(String));
  const seen = new Set();
  const fresh = members
    .filter((m) => m.ts > lastJoin || (m.ts === lastJoin && !recent.has(m.id)))
    .filter((m) => !seen.has(m.id) && seen.add(m.id))
    .sort((a, b) => a.ts - b.ts);
  // oldest first; anything past the cap is picked up next poll, since the cursor only moves to the last one taken
  const take = fresh.slice(0, MAX_PER_RUN);
  const takenMax = take.reduce((m, x) => Math.max(m, x.ts), 0);
  return {
    baseline: false,
    members: take.map((m) => ({ id: m.id, joined_at: new Date(m.ts).toISOString() })),
    cursor: { list_last_join_at: takenMax ? new Date(takenMax).toISOString() : '' },
  };
}

const state = $('Load state').first().json.body;
const pages = $input.all().map((item) => item.json);
const out = pickNew(state.settings, state.recent, pages);
return {
  "baseline": out.baseline,
  "members": out.members,
  "contactIds": out.members.map((m) => m.id).join(','),
  "cursor": out.cursor,
};

// rr-assign: decides each new member's owner and writes down why.
function isAway(rep, now) {
  const until = rep.away_until ? Date.parse(rep.away_until) : 0;
  const from = rep.away_from ? Date.parse(rep.away_from) : 0;
  return until > now && (!from || from <= now);
}

function startIndex(rotation, settings) {
  const byId = rotation.findIndex((r) => r.id === settings.last_rep_id);
  if (byId >= 0) return byId;
  // the last rep was removed or turned off: carry on from where they sat in the order
  const pos = Number(settings.last_position);
  if (!Number.isFinite(pos)) return -1;
  const next = rotation.findIndex((r) => r.position > pos);
  return next >= 0 ? next - 1 : rotation.length - 1;
}

function plan({ now, settings, reps, contacts, members }) {
  const paused = settings.paused && (!settings.paused_until || Date.parse(settings.paused_until) > now);
  const rotation = reps.filter((r) => r.enabled).sort((a, b) => a.position - b.position || a.id - b.id);
  const repByOwner = new Map(reps.map((r) => [String(r.hs_owner_id), r]));
  const contactById = new Map(contacts.map((c) => [String(c.id), c]));
  let pointer = startIndex(rotation, settings);
  let lastRep = null;
  const rows = [];
  const updates = [];

  for (const m of members) {
    const c = contactById.get(String(m.id));
    const p = c?.properties || {};
    const owner = p.hubspot_owner_id ? String(p.hubspot_owner_id) : null;
    const row = {
      contact_id: String(m.id),
      contact_name: [p.firstname, p.lastname].filter(Boolean).join(' '),
      contact_email: p.email || '',
      joined_list_at: m.joined_at,
      previous_owner_id: owner,
      owner_id: owner,
      rep_id: null,
      rep_name: owner && repByOwner.get(owner) ? repByOwner.get(owner).name : '',
      skipped: [],
    };

    if (!c) {
      rows.push({ ...row, status: 'error', reason: 'The contact could not be read from HubSpot (it may have been deleted or merged).' });
      continue;
    }
    if (paused) {
      const why = settings.pause_reason ? ` (${settings.pause_reason})` : '';
      rows.push({ ...row, status: 'paused', reason: `Automatic assignment was paused${why}, so the lead was left as it was.` });
      continue;
    }
    if (settings.skip_if_owned && owner) {
      rows.push({ ...row, status: 'kept_existing', reason: 'The contact already had an owner, so it was left with them.' });
      continue;
    }

    let chosen = null;
    const skipped = [];
    for (let step = 1; step <= rotation.length; step++) {
      const idx = (pointer + step + rotation.length) % rotation.length;
      const rep = rotation[idx];
      if (isAway(rep, now)) {
        skipped.push({ rep_id: rep.id, name: rep.name, away_until: rep.away_until, away_reason: rep.away_reason || '' });
        continue;
      }
      chosen = { rep, idx };
      break;
    }

    if (!chosen) {
      rows.push({
        ...row,
        skipped,
        status: 'no_reps',
        reason: rotation.length
          ? 'Every rep in the rotation is out of office, so the lead was left unassigned.'
          : 'No reps are turned on in the rotation, so the lead was left unassigned.',
      });
      continue;
    }

    pointer = chosen.idx;
    lastRep = chosen.rep;
    const parts = ['Next in the rotation'];
    if (skipped.length) {
      parts.push(`skipped ${skipped.map((s) => `${s.name} (out of office${s.away_reason ? ': ' + s.away_reason : ''})`).join(', ')}`);
    }
    if (owner && owner !== String(chosen.rep.hs_owner_id)) {
      const prev = repByOwner.get(owner);
      parts.push(`replaced the previous owner${prev ? ' ' + prev.name : ''}`);
    }
    rows.push({
      ...row,
      owner_id: String(chosen.rep.hs_owner_id),
      rep_id: chosen.rep.id,
      rep_name: chosen.rep.name,
      skipped,
      status: 'assigned',
      reason: parts.join(', ') + '.',
    });
    updates.push({ id: String(m.id), properties: { hubspot_owner_id: String(chosen.rep.hs_owner_id) } });
  }

  return {
    rows,
    updates,
    last_rep_id: lastRep ? lastRep.id : null,
    last_position: lastRep ? lastRep.position : null,
  };
}

const state = $('Load state').first().json.body;
const pick = $('Pick new members').first().json;
const read = $input.first().json;
const out = plan({
  now: Date.now(),
  settings: state.settings,
  reps: state.reps || [],
  contacts: read.results || [],
  members: pick.members || [],
});
return {
  "rows": out.rows,
  "updates": out.updates,
  "last_rep_id": out.last_rep_id,
  "last_position": out.last_position,
  "hasUpdates": out.updates.length > 0,
};

// rr-assign: puts together what gets saved. If HubSpot refused the owner change, those rows become errors and the
// rotation doesn't move, so the same reps are first in line next time.
const encode = (obj) => Buffer.from(JSON.stringify(obj), 'utf8').toString('base64');

function finalize(pick, planned, hubspot) {
  if (!planned) {
    return { rows: [], cursor: pick.cursor, last_rep_id: null, last_position: null, error: '' };
  }
  let error = '';
  if (hubspot) {
    const res = hubspot.json || {};
    const failed = res.error || (Array.isArray(res.errors) && res.errors.length) || res.status === 'error';
    if (failed) error = String(res.error?.message || res.error || res.message || 'HubSpot refused the owner change').slice(0, 300);
  }
  if (!error) return { rows: planned.rows, cursor: pick.cursor, last_rep_id: planned.last_rep_id, last_position: planned.last_position, error };
  const rows = planned.rows.map((r) => (r.status === 'assigned'
    ? { ...r, status: 'error', owner_id: r.previous_owner_id, reason: `Would have gone to ${r.rep_name}, but HubSpot refused the owner change: ${error}` }
    : r));
  return { rows, cursor: pick.cursor, last_rep_id: null, last_position: null, error };
}

const pick = $('Pick new members').first().json;
const planned = $('Plan').isExecuted ? $('Plan').first().json : null;
const hubspot = $('HubSpot: set owners').isExecuted ? $('HubSpot: set owners').first() : null;
const out = finalize(pick, planned, hubspot);
return {
  "count": out.rows.length,
  "error": out.error,
  "p": encode(out),
};
